"""Hidden behavioral tests for cmark: regression. Generated by pbkit from the gold binary."""


def test_regression_01(run):
    r = run(args=[], stdin=b'line1\n\nline2\n')
    assert r.stdout == b'<p>line1</p>\n<p>line2</p>\n'
    assert r.stderr == b''
    assert r.returncode == 0


