    r = run(args=['-t', 'xml', '--sourcepos'], stdin=b'line1\n\nline2\n')
    assert r.stdout == b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE document SYSTEM "CommonMark.dtd">\n<document sourcepos="1:1-3:5" xmlns="http://commonmark.org/xml/1.0">\n  <paragraph sourcepos="1:1-1:5">\n    <text sourcepos="1:1-1:5" xml:space="preserve">line1</text>\n  </paragraph>\n  <paragraph sourcepos="3:1-3:5">\n    <text sourcepos="3:1-3:5" xml:space="preserve">line2</text>\n  </paragraph>\n</document>\n'
    assert r.stderr == b''
    assert r.returncode == 0


